Name the solid that folds up from this net.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}, scale=0.7]
\draw (0,0) rectangle (2,2);
\draw (2,0) rectangle (4,2);
\draw (4,0) rectangle (6,2);
\draw (6,0) rectangle (8,2);
\draw (0,2)--(2,2)--(1.5,3.5)--(0.5,3.5)--cycle;
\draw (0,0)--(2,0)--(1.5,-1.5)--(0.5,-1.5)--cycle;
